declarations.elaborated_type:
∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] [Nonempty ι] {P U Δ : ℝ → Matrix ι ι ℂ}
  {dP dU dΔ : Matrix ι ι ℂ} {t : ℝ} (β z : ℝ),
  β ≠ 0 →
    0 ≤ z →
      z < 1 →
        HasDerivAt P dP t →
          HasDerivAt U dU t →
            HasDerivAt Δ dΔ t →
              (∀ᶠ (s : ℝ) in nhds t, P s * P s = P s) →
                (∀ᶠ (s : ℝ) in nhds t, star (P s) = P s) →
                  star (U t) * U t = 1 →
                    star (Δ t) = Δ t →
                      have K := D0.Algebra.MovingProjectorTransport.generator (P t) dP;
                      have C := D0.Algebra.MovingProjectorTransport.cut (P t) (U t);
                      have R := (1 - ↑z • (star C * C))⁻¹;
                      have V := (1 - P t) * (dU - D0.Algebra.MovingProjectorTransport.comm K (U t)) * P t;
                      have E := NormedSpace.exp (-β • Δ t);
                      have Z := D0.Analysis.matrixHeatPartition β (Δ t);
                      HasDerivAt (fun s => D0.Algebra.MovingProjectorTransport.movingHeatFeedback β z (P s) (U s) (Δ s))
                        (-(E * (dΔ - D0.Algebra.MovingProjectorTransport.comm K (Δ t))).trace.re / Z +
                          z * (2 * (R * star C * V).trace.re))
                        t
